mapper.select:
select count(id)
from contract_stage_config
where organization_id = #{orgId}

mapper.update:
update contract_stage_config
set pos = pos + #{pos}
where pos >= #{start}
  and organization_id = #{orgId}

update contract_stage_config
set pos = pos + #{pos}
where pos > #{start}
  and organization_id = #{orgId}

update contract_stage_config
set name        = #{request.name},
    update_user = #{userId},
    update_time = unix_timestamp() * 1000
where id = #{request.id}
  and organization_id = #{orgId}

mapper.select:
select id, name, type, afoot_roll_back, end_roll_back, pos, organization_id,
       create_time, update_time, create_user, update_user, circulation_type
from contract_stage_config
where id = #{id}
  and organization_id = #{orgId}

mapper.delete:
delete from contract_stage_config
where id = #{id}
  and organization_id = #{orgId}
